#include <bits/stdc++.h>
using namespace std;

#define SZ(a) int((a).size())
#define ALL(a) (a).begin(), (a).end()
#define debug(...) fprintf(stderr, __VA_ARGS__)
#define fi first
#define se second

template<class T> void cmin(T &a, T b) {a = min(a, b);}
template<class T> void cmax(T &a, T b) {a = max(a, b);}

const double eps = 1e-6;
const double PI = acos(-1);

inline int dcmp(double x) {return x < -eps ? -1 : x > eps;}
struct Point {
  double x, y, d, p, r;
  int id;
  Point(double x = 0, double y = 0) : x(x), y(y) {
    d = 1e18;
    id = -1;
  }
  Point operator+(Point b) {return Point(x + b.x, y + b.y);}
  Point operator-(Point b) {return Point(x - b.x, y - b.y);}
  Point operator*(double p) {return Point(x * p, y * p);}
  double operator*(Point b) {return x * b.x + y * b.y;}
  double operator^(Point b) {return x * b.y - y * b.x;}
  double len() {return sqrt(x * x + y * y);}
  bool operator==(Point b) {return !dcmp(x - b.x) && !dcmp(y - b.y);}
};

const double M = 2 * PI / 3.6e8;

int main() {
  int n, m;
  scanf("%d %d", &n, &m);

  vector<double> R(n);
  vector a(n, vector<pair<double, int>>());
  auto b = a;
  for (int i = 0; i < n; i++) {
    int K;
    scanf("%lf %d", &R[i], &K);
    a[i].resize(K);
    for (int j = 0; j < K; j++) {
      auto &[p, id] = a[i][j];
      scanf("%lf", &p);
      p *= M;
      id = j;
    }
  }

  vector<double> ans(m, 1e18);
  for (int i = 0; i < m; i++) {
    int t;
    double q;
    scanf("%d %lf", &t, &q);
    b[--t].push_back(make_pair(q * M, -1 - i));
  }

  vector<double> f(SZ(a[0]), R[0]);
  for (auto [_, i] : b[0]) ans[-i - 1] = R[0];

  for (int i = 1; i < n; i++) {
    auto ts = [&](double r, double p)->Point {
      return Point(r * cos(p), r * sin(p));
    };
    auto dis = [&](double u, double v) {
      return (ts(R[i], u) - ts(R[i - 1], v)).len();
    };

    if (SZ(a[i - 1]) == 0) break;

    double th = acos(R[i - 1] / R[i]);
    auto bck = a[i];

    auto calc = [&](double u, double v) {
      auto cc = [&](double w) {
        double ag = v - w;
        while (ag < 0) ag += 2 * PI;
        while (ag >= 2 * PI) ag -= 2 * PI;
        ag = min(ag, 2 * PI - ag);
        return sqrt(R[i] * R[i] - R[i - 1] * R[i - 1]) + R[i - 1] * ag;
      };
      return min(cc(u + th), cc(u - th));
    };

    a[i].insert(a[i].end(), ALL(b[i]));
    sort(ALL(a[i]));

    auto tmp1 = a[i - 1], tmp2 = a[i - 1];
    for (auto &x : tmp1) x.fi -= 2 * PI;
    for (auto &x : tmp2) x.fi += 2 * PI;
    a[i - 1].insert(a[i - 1].begin(), ALL(tmp1));
    a[i - 1].insert(a[i - 1].end(), ALL(tmp2));

    vector<double> g(SZ(a[i]), 1e18);
    vector<int> sl(SZ(a[i])), sr(SZ(a[i]));
    for (int j = 0, l = 0, r = 0; j < SZ(a[i]); j++) {
      while (r < SZ(a[i - 1]) && dcmp(a[i - 1][r].fi - a[i][j].fi - th) <= 0) r++;
      while (l < SZ(a[i - 1]) && dcmp(a[i - 1][l].fi - a[i][j].fi + th) < 0) l++;
      sl[j] = l, sr[j] = r;
      for (auto cur : {r % SZ(a[i - 1]), (l - 1 + SZ(a[i - 1])) % SZ(a[i - 1])}) {
        cmin(g[j], calc(a[i][j].fi, a[i - 1][cur].fi) + f[a[i - 1][cur].se]);
      }
    }

    auto solve = [&](auto self, int l, int r, int ql, int qr)->void {
      if (l > r || ql > qr) return;
      int o = (l + r) / 2, bl = max(ql, sl[o]), br = min(qr, sr[o] - 1);
      pair<double, int> res{1e18, bl};
      for (int j = bl; j <= br; j++) {
        cmin(res, {dis(a[i][o].fi, a[i - 1][j].fi) + f[a[i - 1][j].se], j});
      }
      cmin(g[o], res.fi);
      self(self, l, o - 1, ql, res.se);
      self(self, o + 1, r, res.se, qr);
    };
    solve(solve, 0, SZ(a[i]) - 1, 0, SZ(a[i - 1]) - 1);

    f.resize(SZ(bck));
    for (int j = 0; j < SZ(a[i]); j++) {
      if (a[i][j].se < 0) ans[-a[i][j].se - 1] = g[j];
      else f[a[i][j].se] = g[j];
    }
    a[i] = bck;
  }

  for (int i = 0; i < m; i++) {
    if (dcmp(ans[i] - 1e18) >= 0) printf("-1\n");
    else printf("%.10lf\n", ans[i]);
  }
  return 0;
}
