题目是说，有 $n$ 个知识点，其中 $m$ 没有依赖，剩下 $n - m$ 个有唯一的依赖，且依赖的那个知识点没有依赖，现在要按一个顺序学习所有知识点，要求满足依赖关系，每个知识点有一个权值 $w_i$，最小化重排后的 $\sum |w_{i + 1} - w_i|$。

好像就没有正经人话题解，但是是简单题。

这个题在数轴上刻画是对的。

如果没有依赖肯定从小走到大。

这里钦定一个起点 $S$ 和终点 $T$，并且可以钦定 $S < T$，否则可以把数轴翻过来再做一遍。

离散化一下。

注意到 $1, n$ 是必经点，所以 $(1, S), (T, n)$ 至少经过 $2$ 次，$(S, T)$ 至少经过一次。

一种路线是 $S\to 1\to n\to T$，刚好卡在下界。

然后考虑依赖，显然如果依赖在 $(1, S), (T, n)$ 内部没关系，可以在走第一遍的时候拿走所有无依赖点，走回来的时候拿走所有有依赖点。

然后注意到 $(S, S + 1), (T - 1, T)$ 如果被依赖覆盖了，肯定不优，因为可以把 $S, T$ 向中间移动获得更优解。

所以依赖被划分成了两部分，现在来考虑 $(S, T)$ 内部的依赖。

一个依赖 $(u, v)$ 说明必须要 $v\to u$，而你需要 $S\to T$，所以必须至少是 $u\to v\to u\to v$，覆盖 $3$ 次。

中间的这些依赖线段取并即可，所以找到了确定 $S, T$ 之后的下界和构造方案，显然 $S, T$ 可以分开枚举，于是就做完了。

沃日咋是最劣解，咋这么慢。

```cpp
#include <bits/stdc++.h>
using namespace std;

#define ALL(a) (a).begin(), (a).end()
#define SZ(a) int(a.size())
#define fi first
#define se second

using LL = long long;

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int n, m;
  cin >> n >> m;
  vector<LL> w(n);
  for (int i = 0; i < n; i++) cin >> w[i];
  vector<int> p(n);
  for (int i = m; i < n; i++) cin >> p[i], p[i]--;

  LL ans = 2e18;
  vector<int> ouf;
  auto sol = [&]() {
    auto w_ = w;
    sort(ALL(w_));
    w_.erase(unique(ALL(w_)), w_.end());
    int k = SZ(w_);
    vector A(k, vector<int>()), B = A;
    vector<int> _w(n);
    for (int i = 0; i < n; i++)
      _w[i] = lower_bound(ALL(w_), w[i]) - w_.begin();
    for (int i = 0; i < m; i++) A[_w[i]].emplace_back(i);
    for (int i = m; i < n; i++) B[_w[i]].emplace_back(i);

    vector<int> s(k);
    for (int i = m; i < n; i++) {
      int l = _w[i], r = _w[p[i]];
      if (l < r) s[l]++, s[r]--;
    }
    partial_sum(ALL(s), s.begin());

    LL res = 2 * (w_[k - 1] - w_[0]), bas = 0;
    for (int i = 0; i < k - 1; i++) {
      bas += (w_[i + 1] - w_[i]) * (s[i] ? 3 : 1);
    }
    int S = -1, T = -1;
    vector<pair<LL, int>> ss(k);
    ss[0] = {0, 0};
    for (int i = 1; i < k; i++) {
      ss[i] = {ss[i - 1].fi + (s[i - 1] ? -1 : 1) * (w_[i] - w_[i - 1]), i};
    }
    for (int i = 1; i < k; i++) ss[i] = min(ss[i], ss[i - 1]);

    LL tt = 0;
    for (int i = k - 1; i >= 0; i--) {
      if (i + 1 < k) {
        tt += (s[i] ? -1 : 1) * (w_[i + 1] - w_[i]);
      }
      if (i && s[i - 1]) continue;
      LL now = bas + ss[i].fi + tt;
      if (now < res) res = now, S = ss[i].se, T = i;
    }

    vector<int> nuf;
    if (S == -1 && T == -1) {
      for (int i = 0; i < k; i++) for (auto u : A[i]) nuf.emplace_back(u);
      for (int i = k - 1; i >= 0; i--) for (auto u : B[i]) nuf.emplace_back(u);
      goto sk;
    }
    for (int i = S; i >= 0; i--) for (auto u : A[i]) nuf.emplace_back(u);
    for (int i = 0; i <= S; i++) for (auto u : B[i]) nuf.emplace_back(u);
    for (int i = S + 1; i < T; i++) {
      if (s[i]) {
        int j = i;
        while (j + 1 < T && s[j + 1]) j++;
        j++;
        for (int o = i; o <= j; o++) for (auto u : A[o]) nuf.emplace_back(u);
        for (int o = j; o >= i; o--) for (auto u : B[o]) nuf.emplace_back(u);
        i = j;
        continue;
      }
      for (auto u : A[i]) nuf.emplace_back(u);
      for (auto u : B[i]) nuf.emplace_back(u);
    }
    for (int i = T; i < k; i++) for (auto u : A[i]) nuf.emplace_back(u);
    for (int i = k - 1; i >= T; i--) for (auto u : B[i]) nuf.emplace_back(u);

    sk:
    if (res < ans) ans = res, ouf = nuf;
  };
  sol();
  for (int i = 0; i < n; i++) w[i] = 1e12 - w[i];
  sol();
  cout << ans << "\n";
  for (auto u : ouf) cout << u + 1 << " ";
  cout << "\n";
  return 0;
}
